import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"坎","description":"周易集解 - 坎","frontmatter":{"title":"坎","description":"周易集解 - 坎"},"headers":[],"relativePath":"zh/classics/jijie/029.md","filePath":"zh/classics/jijie/029.md"}'),l={name:"zh/classics/jijie/029.md"};function n(p,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="坎" tabindex="-1">坎 <a class="header-anchor" href="#坎" aria-label="Permalink to “坎”">​</a></h1><h2 id="坎-1" tabindex="-1">坎 <a class="header-anchor" href="#坎-1" aria-label="Permalink to “坎”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>坎，習坎，有孚。維心亨，行有尚。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以終過，故受之以坎。坎者，陷也。</p><p>崔憬曰：大過不可以極，極則過涉滅頂，故曰｢物不可以終過，故受之以坎｣也。</p><p>虞翻曰：乾二五之坤，與離旁通。於爻，觀上之二。習，常也。孚，信，謂二五。水行往來，朝宗於海，不失其時，如月行天，故習坎為孚也。</p><p>虞翻曰：坎為心。乾二五旁行流坤，陰陽會合，故亨也。</p><p>虞翻曰：行謂二，尚謂五也。二位震為行，動得正應五，故｢行有尚，往有功也｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：習坎，重險也。水流而不盈，行險而不失其信。維心亨，乃以剛中也。行有尚，往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國，險之時用大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：兩象也。天險地險，故曰重險也。</p><p>荀爽曰：陽動陰中，故流。陽陷陰中，故不盈也。</p><p>陸績曰：水性趨下，不盈溢崖岸也。月者水精，月在天，滿則虧，不盈溢之義也。</p><p>荀爽曰：謂陽來為險，而不失中。中稱信也。</p><p>虞翻曰：信，謂二也。震為行。水性有常，消息與月相應，故不失其信矣。</p><p>侯果曰：二五剛而居中，則心亨也。</p><p>虞翻曰：功謂五。二動應五，故往有功也。</p><p>虞翻曰：謂五在天位。五從乾來，體屯難。故天險不可升也。</p><p>虞翻曰：坤為地，乾二之坤，故曰地險。艮為山，坎為川；半山稱丘，丘下稱陵。故曰｢地險山川丘陵也｣。</p><p>虞翻曰：王公大人謂乾五。坤為邦。乾二之坤成坎險，震為守，有屯難象。故｢王公設險以守其國｣。離言王用出征以正邦是也。</p><p>案：九五，王也，六三，三公也。艮為山城，坎為水也。王公設險之象也。</p><p>王肅曰：守險以德，據險以時，成功大矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：水洊至，習坎。君子以常德行習教事。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>陸績曰：洊，再。習，重也。水再至而益，通流不舍晝夜。重習相隨以為常，有似於習，故君子象之。以常習教事，如水不息也。</p><p>虞翻曰：君子謂乾。五在乾，稱大人；在坎，為君子。坎為習、為常，乾為德，震為行，巽為教令，坤為事，故｢以常德行習教事｣也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，習坎，入於坎窞，凶。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>乾寶曰：窞，坎之深者也。江河淮濟，百川之流行乎地中，水之正也。及其為災，則泛溢平地，而入於坎窞，是水失其道也。刑獄之用，必當於理，刑之正也。及其不平，則枉濫無辜，是法失其道也。故曰｢入於坎窞，凶｣矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：習坎入坎，失道凶也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：習，積也。位下，故習坎為入。坎中小穴稱窞。上無其應，初二失正，故曰失道凶矣。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，坎有險，求小得。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：陽陷陰中，故有險。據陰有實，故求小得也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：求小得，未出中也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：處中而比初三，未足為援。雖求小得，未出於險中。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，來之坎坎，險且枕，入於坎窞，勿用。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坎在內稱來，在坎終坎，故｢來之坎坎｣。枕，止也。艮為止。三失位乘二，則險。承五隔四，故險且枕。入於坎窞，體師三輿，故勿用。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：來之坎坎，終無功也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>乾寶曰：坎，十一月卦也。又失其位，喻殷之執法者，失中之象也。來之坎者，斥周人觀釁於殷也。枕，安也。險且枕者，言安忍以暴政加民，而無哀矜之心，淫刑濫罰，百姓無所措手足，故曰｢來之坎坎，終無功也｣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，樽酒簋，貳用缶。納約自牖，終無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：震主祭器，故有樽簋。坎為酒。簋，黍稷器。三至五，有頤口象。震獻在中，故為簋。坎為木，震為足；坎酒在上，樽酒之象。貳，副也。坤為缶，禮有副樽，故貳用缶耳。</p><p>虞翻曰：坎為納也。四陰小，故約。艮為牖，坤為戶，艮小光，照戶牖之象。貳用缶，故納約自牖。得位承五，故無咎。</p><p>崔憬曰：於重險之時，居多懼之地，近三而得位，比五而承陽。修其絜誠，進其忠信，則雖祭祀省薄，明德惟馨。故曰｢樽酒簋貳用缶｣。納約，文王於紂時行此道，從羑里納約，卒免於難，故曰｢自牖，終無咎也｣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：樽酒簋貳，剛柔際也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乾剛坤柔，震為交，故曰剛柔際也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，坎不盈，祇既平，無咎。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：盈，溢也。艮為止，謂水流而不盈。坎為平。祇，安也。艮止坤安，故祇既平。得位正中，故無咎。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：坎不盈，中未光大也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：體屯五中，故未光大也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六：係用徽纆，寘於叢棘，三歲不得，凶。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：徽纆，黑索也。觀巽為繩，艮為手，上變入坎。故係用徽繩。寘，置也。坎多心，故叢棘。獄外種九棘，故稱叢棘。二變則五體剝，剝傷坤殺，故寘於叢棘也。不得，謂不得出獄。艮止坎獄。乾為歲，五從乾來，三非其應，故曰｢三歲不得，凶｣矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：上六失道，凶三歲也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：坎為叢棘，又為法律。</p><p>案《周禮》：王之外朝，左九棘，右九棘，面三槐，司寇公卿議獄於其下。害人者，加明刑。任之以事。上罪三年舍，中罪二年而舍，下罪一年而舍也。</p><p>案：坎於木堅而多心，叢棘之象也。坎下巽爻，巽為繩直，係用徽纆也。馬融雲：徽纆，索也。劉表雲：三股為徽，兩股為纆，皆索名。以繫縛其罪人矣。</p>',82)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
